begin;
select no_plan();
select ok(not has_function_privilege('anon','api.execute_owner_block_controls_server(uuid,text,jsonb)','EXECUTE'),'Anonymous gateway denied');
select ok(not has_function_privilege('authenticated','api.execute_owner_block_controls_server(uuid,text,jsonb)','EXECUTE'),'Browser cannot select subject');
select ok(has_function_privilege('service_role','api.execute_owner_block_controls_server(uuid,text,jsonb)','EXECUTE'),'Server gateway enabled');
set local role anon;
select throws_ok($$select api.execute_owner_block_controls_server(null,null,'{}')$$,'42501',null,'Actual anonymous call denied');
reset role;
set local role authenticated;
select throws_ok($$select api.execute_owner_block_controls_server(null,null,'{}')$$,'42501',null,'Actual browser call denied');
reset role;
select ok(not has_function_privilege('service_role','api.save_current_owner_block_visibility_working(jsonb)','EXECUTE'),'Original initialization withheld');
select ok(not has_function_privilege('service_role','api.move_current_owner_block_working(jsonb)','EXECUTE'),'Original append withheld');
select ok(not has_function_privilege('service_role','api.remove_current_owner_block_working(jsonb)','EXECUTE'),'Original save withheld');
insert into auth.users(id,email) values('27300000-0000-4000-8000-000000000001','text-gateway-one@example.test'),('27300000-0000-4000-8000-000000000002','text-gateway-two@example.test');
create temporary table actors as select auth_user_id,owner_id from core.owner_auth_bindings where auth_user_id in('27300000-0000-4000-8000-000000000001','27300000-0000-4000-8000-000000000002');
update core.owner_onboarding_progress set current_step='preview_publish',primary_use_case='personal' where owner_id in(select owner_id from actors);
insert into core.owner_handle_namespaces(normalized_handle,owner_id,namespace_kind) select 'text273-'||right(auth_user_id::text,6),owner_id,'current' from actors;
update core.owners set onboarding_completed_at=now() where id in(select owner_id from actors);
insert into core.identity_working(owner_id,display_name,bio,revision) select owner_id,'Source Profile','Retained Bio',2 from actors;
insert into core.identity_layout_working(owner_id,starter_key,revision) select owner_id,'clean',1 from actors;
insert into core.identity_publications(owner_id,snapshot,identity_revision,layout_revision,connection_revision,published_at) select owner_id,'{"legacy":true}',2,1,null,now() from actors;
create temporary table created(actor uuid,result jsonb);
grant select,insert on created to service_role;
create function pg_temp.add_text(subject uuid,base bigint) returns jsonb language sql as $$ select api.execute_owner_text_editor_server(subject,case when base is null then 'initialize_current_owner_blocks_from_text' else 'add_current_owner_text_block_working' end,jsonb_build_object('input_intent',jsonb_build_object('action',case when base is null then 'initialize_text_block' else 'add_text_block' end,'base_collection_revision',base,'is_visible',false,'text_working',jsonb_build_object('kind','text','text',' Raw <text> '))));$$;
create function pg_temp.control(subject uuid,operation text,base bigint,target uuid,extra jsonb) returns jsonb language sql as $$ select api.execute_owner_block_controls_server(subject,operation,jsonb_build_object('input_working',jsonb_build_object('block_id',target,'base_collection_revision',base)||extra));$$;
grant execute on function pg_temp.add_text(uuid,bigint),pg_temp.control(uuid,text,bigint,uuid,jsonb) to service_role;
set local request.jwt.claims='{"role":"service_role","sub":"27300000-0000-4000-8000-000000000002"}';
set local request.jwt.claim.sub='27300000-0000-4000-8000-000000000002';
set local role service_role;
insert into created select '27300000-0000-4000-8000-000000000001',pg_temp.add_text('27300000-0000-4000-8000-000000000001',null);
insert into created select '27300000-0000-4000-8000-000000000001',pg_temp.add_text('27300000-0000-4000-8000-000000000001',1);
insert into created select '27300000-0000-4000-8000-000000000002',pg_temp.add_text('27300000-0000-4000-8000-000000000002',null);
select is(pg_temp.control('27300000-0000-4000-8000-000000000001','save_current_owner_block_visibility_working',2,(select (result->>'block_id')::uuid from created where actor='27300000-0000-4000-8000-000000000001' limit 1),'{"is_visible":true}')->>'collection_revision','3','Visibility saved through actual service gateway');
select is(pg_temp.control('27300000-0000-4000-8000-000000000001','save_current_owner_block_visibility_working',2,(select (result->>'block_id')::uuid from created where actor='27300000-0000-4000-8000-000000000001' limit 1),'{"is_visible":false}')->>'status','stale_write','Stale visibility replay denied');
select is(pg_temp.control('27300000-0000-4000-8000-000000000001','move_current_owner_block_working',3,(select (result->>'block_id')::uuid from created where actor='27300000-0000-4000-8000-000000000001' limit 1),'{"direction":"down"}')->>'collection_revision','4','Server adjacent movement saves exact next revision');
select is(pg_temp.control('27300000-0000-4000-8000-000000000001','move_current_owner_block_working',4,(select (result->>'block_id')::uuid from created where actor='27300000-0000-4000-8000-000000000001' limit 1),'{"direction":"down"}')->>'status','move_not_available','Last down is known no-write boundary');
select is(current_setting('request.jwt.claim.sub'),'27300000-0000-4000-8000-000000000002','Gateway restores prior subject');
reset role;
select is((select position::text from core.identity_blocks_working where block_id=(select (result->>'block_id')::uuid from created where actor='27300000-0000-4000-8000-000000000001' limit 1)),'2','Actual target position swapped');
select ok((select is_visible from core.identity_blocks_working where block_id=(select (result->>'block_id')::uuid from created where actor='27300000-0000-4000-8000-000000000001' limit 1)),'Move retains visibility');
select ok(not exists(select 1 from core.identity_block_texts_working where owner_id in(select owner_id from actors) and text_content<>' Raw <text> '),'Visibility and move preserve every raw payload');
set local role service_role;
select is(pg_temp.control('27300000-0000-4000-8000-000000000001','remove_current_owner_block_working',4,(select (result->>'block_id')::uuid from created where actor='27300000-0000-4000-8000-000000000001' limit 1),'{"confirm_removal":false}')->>'status','invalid_block_removal','Unchecked removal denied');
select is(pg_temp.control('27300000-0000-4000-8000-000000000001','remove_current_owner_block_working',4,(select (result->>'block_id')::uuid from created where actor='27300000-0000-4000-8000-000000000001' limit 1),'{"confirm_removal":true}')->>'collection_revision','5','Confirmed scoped removal acknowledged');
select is(pg_temp.control('27300000-0000-4000-8000-000000000001','remove_current_owner_block_working',4,(select (result->>'block_id')::uuid from created where actor='27300000-0000-4000-8000-000000000001' limit 1),'{"confirm_removal":true}')->>'status','stale_write','Removed stale intent cannot replay');
select is(pg_temp.control('27300000-0000-4000-8000-000000000001','remove_current_owner_block_working',5,(select (result->>'block_id')::uuid from created where actor='27300000-0000-4000-8000-000000000002' limit 1),'{"confirm_removal":true}')->>'status','block_not_found','Foreign target denied without existence oracle');
select is(api.execute_owner_block_controls_server('27300000-0000-4000-8000-000000000001','publish_current_onboarding','{}')->>'status','unavailable','No arbitrary operation');
select is(api.execute_owner_block_controls_server('27300000-0000-4000-8000-000000000001','move_current_owner_block_working','{"input_working":{},"owner_id":"forged"}')->>'status','unavailable','Extra Owner envelope denied');
reset role;
select is((select count(*)::int from core.identity_block_texts_working where block_id=(select (result->>'block_id')::uuid from created where actor='27300000-0000-4000-8000-000000000001' limit 1)),0,'Only removed typed payload cascades');
select is((select count(*)::int from core.identity_block_texts_working where owner_id in(select owner_id from actors)),2,'Other and foreign payloads retained');
create function pg_temp.fail_remove() returns trigger language plpgsql as $$begin raise exception 'fixture delete failure';end;$$;
create trigger controls_fixture before delete on core.identity_blocks_working for each row execute function pg_temp.fail_remove();
set local role service_role;
select throws_ok($$select pg_temp.control('27300000-0000-4000-8000-000000000001','remove_current_owner_block_working',5,(select (result->>'block_id')::uuid from created where actor='27300000-0000-4000-8000-000000000001' and result->>'collection_revision'='2'),'{"confirm_removal":true}')$$,'P0001','fixture delete failure','Removal exception rolls back');
select is(current_setting('request.jwt.claims')::jsonb,'{"role":"service_role","sub":"27300000-0000-4000-8000-000000000002"}'::jsonb,'Exception restores complete caller claims');
reset role;
drop trigger controls_fixture on core.identity_blocks_working;
select is((select revision::text from core.identity_block_collections_working where owner_id=(select owner_id from actors where auth_user_id='27300000-0000-4000-8000-000000000001')),'5','Failed removal does not advance revision');
set local role service_role;
select is(pg_temp.control('27300000-0000-4000-8000-000000000001','remove_current_owner_block_working',5,(select (result->>'block_id')::uuid from created where actor='27300000-0000-4000-8000-000000000001' and result->>'collection_revision'='2'),'{"confirm_removal":true}')->>'collection_revision','6','Last block removal retains explicit empty collection');
reset role;
select is((select count(*)::int from core.identity_blocks_working where owner_id=(select owner_id from actors where auth_user_id='27300000-0000-4000-8000-000000000001')),0,'No target members remain');
select is((select revision::text from core.identity_block_collections_working where owner_id=(select owner_id from actors where auth_user_id='27300000-0000-4000-8000-000000000001')),'6','Empty collection preserved at exact revision');
update core.owners set account_state='restricted' where id=(select owner_id from actors where auth_user_id='27300000-0000-4000-8000-000000000002');
set local role service_role;
select is(pg_temp.control('27300000-0000-4000-8000-000000000002','remove_current_owner_block_working',1,(select (result->>'block_id')::uuid from created where actor='27300000-0000-4000-8000-000000000002'),'{"confirm_removal":true}')->>'status','owner_not_eligible','Restriction denies removal');
reset role;
select ok(not exists(select 1 from core.identity_publications where owner_id in(select owner_id from actors) and snapshot<>'{"legacy":true}'::jsonb),'Published snapshots preserved');
select ok(not exists(select 1 from core.identity_working where owner_id in(select owner_id from actors) and (display_name<>'Source Profile' or revision<>2)),'Profile unchanged');
select * from finish();
rollback;
